import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.BQq6mqvm.js";const g=JSON.parse('{"title":"整理文件夹","description":"","frontmatter":{},"headers":[],"relativePath":"usage/folders.md","filePath":"usage/folders.md","lastUpdated":1790385461000}'),s={name:"usage/folders.md"};function l(d,t,n,i,c,p){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="整理文件夹" tabindex="-1">整理文件夹 <a class="header-anchor" href="#整理文件夹" aria-label="Permalink to &quot;整理文件夹&quot;">​</a></h1><p>文件多了以后，用文件夹把「我的文件」整理成一棵树，找起来快得多。</p><h2 id="新建文件夹" tabindex="-1">新建文件夹 <a class="header-anchor" href="#新建文件夹" aria-label="Permalink to &quot;新建文件夹&quot;">​</a></h2><p>进入<strong>我的文件</strong>，点右上角的<strong>新建文件夹</strong>，输入名字即可。</p><ul><li>想建子文件夹，先<strong>点进</strong>某个文件夹，再点新建 —— 新文件夹会建在当前这一层里。</li><li>同一层里不能有同名文件夹，重名会提示你换一个。</li><li>文件夹名里的 <code>/ \\ : * ? &quot; &lt; &gt; |</code> 这些符号会被自动去掉（它们不是合法的文件名）。</li></ul><h2 id="进入和返回" tabindex="-1">进入和返回 <a class="header-anchor" href="#进入和返回" aria-label="Permalink to &quot;进入和返回&quot;">​</a></h2><p>文件夹和文件是<strong>在同一个列表里</strong>的（和 Windows 资源管理器一样）， 文件夹排在文件前面，一眼就能看出这一层有哪些目录、哪些文件。</p><p>点文件夹所在的那一行就进入该文件夹，列表里只会显示这个文件夹里的文件。</p><p>列表上方的<strong>面包屑</strong>（比如 <code>我的文件 / 报表 / 2026</code>）会显示你当前的位置：</p><ul><li>点<strong>我的文件</strong>回到最外层；</li><li>点中间任意一层，直接跳回那一层。</li></ul><h2 id="改名字、挪位置、删除" tabindex="-1">改名字、挪位置、删除 <a class="header-anchor" href="#改名字、挪位置、删除" aria-label="Permalink to &quot;改名字、挪位置、删除&quot;">​</a></h2><p>文件夹那一行的右侧有三个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td>分享</td><td>生成这个文件夹的分享链接（见<a href="./share">分享文件与文件夹</a>）</td></tr><tr><td>改名</td><td>改文件夹名字</td></tr><tr><td>删除</td><td>删除文件夹<strong>以及里面的所有文件</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">删除文件夹会连里面的文件一起删</p><p>删除后文件夹里的文件会进入<strong>回收站</strong>（和直接删文件一样），管理员还能恢复； 超过回收站保留天数才会被真正清理掉。</p><p>如果你只是想调整结构，用<strong>改名</strong>就够了；需要连文件一起挪走时再考虑删除后重建。</p></div><h2 id="上传到指定文件夹" tabindex="-1">上传到指定文件夹 <a class="header-anchor" href="#上传到指定文件夹" aria-label="Permalink to &quot;上传到指定文件夹&quot;">​</a></h2><p><strong>先点进那个文件夹</strong>，再把文件拖到页面任意位置松手（或点<strong>上传文件</strong>按钮选文件） —— 文件就会传到当前所在的那一层，不会堆在最外层。</p><p>上传进度、断点续传都和以前一样：网断了刷新页面，还没传完的会接着传。</p><div class="tip custom-block"><p class="custom-block-title">每个人有自己的文件夹树</p><p>文件夹是你自己的，别人看不到你的文件夹结构。展开左侧「全部文件」、点某个人的名字时， 看到的是那个人的文件夹树（别人的文件夹你只能浏览和下载，不能改）。</p></div>',18)])])}const u=a(s,[["render",l]]);export{g as __pageData,u as default};
